SELECT d.connection_id AS "connection_id?",d.external_message_id AS "external_message_id?",d.destination AS "destination?",d.status AS "delivery_status?",m.id,m.thread_id,m.participant_id,m.text,m.status,m.in_reply_to_message_id,m.created_at,m.format,m.subject,m.invocation_id,COALESCE((SELECT jsonb_agg(jsonb_build_object('id',a.id,'thread_id',a.thread_id,'filename',a.filename,'media_type',a.media_type,'size_bytes',a.size_bytes,'sha256',a.sha256) ORDER BY a.id) FROM chat_message_attachments ma JOIN chat_attachments a ON a.id=ma.attachment_id WHERE ma.message_id=m.id),'[]'::jsonb) AS "attachments!: AttachmentRecords",ARRAY(SELECT participant_id FROM chat_message_targets WHERE message_id=m.id ORDER BY participant_id) AS "targets!" FROM chat_messages m LEFT JOIN chat_message_deliveries d ON d.message_id=m.id WHERE m.thread_id=$1 AND ($4::UUID IS NULL OR m.invocation_id=$4 OR (m.created_at,m.id)<=(
 SELECT anchor.created_at,anchor.id FROM chat_invocations invocation JOIN chat_messages anchor ON anchor.id=invocation.history_through_message_id
 WHERE invocation.id=$4 AND invocation.thread_id=$1)) AND ($3::UUID IS NULL OR (m.created_at,m.id)<(SELECT created_at,id FROM chat_messages WHERE id=$3 AND thread_id=$1)) ORDER BY m.created_at DESC,m.id DESC LIMIT $2;
